package com.kafka.backend.money;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static com.kafka.backend.money.MoneyTypes.*;
import static org.assertj.core.api.Assertions.*;

/** Fresh synthetic schema per test; durable writes reread through JDBC, never production fixtures. */
@EnabledIfEnvironmentVariable(named="DEV_DB_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:55467/postgres.*")
class MoneyReviewV2PostgresTest {
 final MoneyRecommendationPostgresTest f=new MoneyRecommendationPostgresTest();
 MoneyOwnerReviewService review;
 @BeforeEach void setup()throws Exception{f.create();f.db.update("update money_accounts set masked_reference='975-******-01-014' where id=?",f.account);review=new MoneyOwnerReviewService(f.db,()->f.owner,f.json,f.money,f.commands);}
 @AfterEach void cleanup(){f.cleanup();}
 UUID raw(boolean out,String counterpart,String reference){return new TransactionTemplate(f.manager).execute(s->{
  var r=f.money.ingest(Map.of("sourcePackage","com.ibk.android.ionebank","title","입출금내역 알림","text","["+(out?"출금":"입금")+"] 5,800원 "+counterpart+" "+reference+" 09/16 10:00 / 잔액 50,000원","postedAt","2026-09-16T01:00:00Z","idempotencyKey",UUID.randomUUID().toString(),"currency","KRW")).notification();
  f.money.process(r.id(),new IbkNotificationParserV1());f.money.finishProcessing(r.id(),ProcessingState.REVIEW_REQUIRED,"OWNER_DECISION");return r.id();
 });}
 UUID raw(boolean out,String counterpart){return raw(out,counterpart,"975-******-01-014");}
 MoneyOwnerReviewService.Decision decision(UUID id,String type,Map<String,Object> extra){
  var fields=new LinkedHashMap<String,Object>();fields.put("type",type);fields.putAll(extra);
  return new MoneyOwnerReviewService.Decision(UUID.randomUUID(),review.context(id).get("fingerprint").toString(),"REGISTER",f.account,(UUID)fields.remove("otherAccountId"),null,f.money.account(f.account).version(),(Long)fields.remove("otherAccountVersion"),null,f.json.convertValue(fields,MoneyOwnerReviewService.Financial.class));
 }
 UUID applied(Map<String,Object> result){assertThat(result).containsEntry("status","APPLIED");return UUID.fromString(((Map<?,?>)result.get("result")).get("transactionId").toString());}
 void noFact(Map<String,Object> result){assertThat(result).containsEntry("status","NOT_APPLIED");assertThat(f.db.queryForObject("select count(*) from money_transaction_sources",Long.class)).isZero();}
 MoneyProcessingService processor(){return new MoneyProcessingService(f.db,f.json,f.manager,Clock.systemUTC(),Duration.ZERO,Duration.ofSeconds(60));}
 void schedule(UUID id){f.db.update("update money_raw_notifications set processing_due_at=now(),received_at=now()-interval '30 seconds' where id=?",id);}
 @Test void unknownMeaningAutoAdmitsCashAndDoesNotInflateConsumption(){var id=raw(true,"의미불명상대");schedule(id);assertThat(processor().runOwner(f.owner)).isEqualTo(1);var t=f.db.queryForMap("select * from money_transactions");assertThat(t.get("meaning_state")).isEqualTo("UNRESOLVED");assertThat(f.product.balance(f.account).amount()).isEqualByComparingTo("50000");assertThat(f.db.queryForObject("select count(*) from money_transactions where meaning_state='CONFIRMED'",Long.class)).isZero();assertThat(processor().runOwner(f.owner)).isZero();}
 @Test void ordinaryOutAndInAdmitWithoutCategory(){for(boolean out:List.of(true,false)){var id=raw(out,out?"합성카페":"합성 급여");schedule(id);assertThat(processor().runOwner(f.owner)).isEqualTo(1);}assertThat(f.db.queryForObject("select count(*) from money_transactions where meaning_state='CONFIRMED' and category_id is null",Long.class)).isEqualTo(2);}
 @Test void dedicatedWordingAdmitsUnresolvedWithoutInventingLoan(){var id=raw(true,"대출상환");schedule(id);assertThat(processor().runOwner(f.owner)).isEqualTo(1);assertThat(f.db.queryForMap("select meaning_state,loan_id from money_transactions")).containsEntry("meaning_state","UNRESOLVED").containsEntry("loan_id",null);}
 @Test void archivedSourceIsNeverRescheduledOrConsumed(){var id=raw(true,"합성카페");f.db.update("update money_raw_notifications set review_deferred=true where id=?",id);schedule(id);assertThat(processor().runOwner(f.owner)).isZero();assertThat(f.money.notification(id).state()).isEqualTo(ProcessingState.REVIEW_REQUIRED);assertThat(f.db.queryForObject("select review_deferred from money_raw_notifications where id=?",Boolean.class,id)).isTrue();}
 @Test void archivedNeighborPreventsAutomaticOppositeConsumption(){UUID a=raw(true,"내계좌"),b=raw(false,"내계좌","975-******-01-015");f.money.createAccount(new AccountInput("IBK","다른 소유 계좌",AccountRole.SPENDING,"975-******-01-015",null));f.db.update("update money_raw_notifications set review_deferred=true where id=?",a);schedule(b);assertThat(processor().runOwner(f.owner)).isZero();assertThat(f.db.queryForObject("select count(*) from money_transactions",Long.class)).isZero();}
 @Test void ownerCorrectionIsAtomicAndRawIsImmutable(){var id=raw(true,"합성카페");var before=f.money.notification(id).rawPayload();var request=decision(id,"INCOME",Map.of("direction","IN","amount",6000,"occurredAt","2026-09-17T02:00:00Z","reason","소유자가 원문과 실제 내역을 비교하여 정정"));var result=review.decide(id,request);var t=f.money.transaction(applied(result));assertThat(t.type()).isEqualTo(TransactionType.INCOME);assertThat(t.amount()).isEqualByComparingTo("6000");assertThat(t.toAccountId()).isEqualTo(f.account);assertThat(f.money.notification(id).rawPayload()).isEqualTo(before);assertThat(review.decide(id,request)).isEqualTo(result);assertThat(f.db.queryForObject("select count(*) from money_meaning_audit where action='OWNER_REVIEW_FINANCIAL_V2'",Long.class)).isEqualTo(1);}
 @Test void correctionWithoutReasonDoesNotConsumeRaw(){var id=raw(true,"합성카페");noFact(review.decide(id,decision(id,"INCOME",Map.of("direction","IN"))));assertThat(f.money.notification(id).state()).isEqualTo(ProcessingState.REVIEW_REQUIRED);}
 @Test void independentCategoryIsOptionalAndOwnerScoped(){var id=raw(true,"합성카페");var t=f.money.transaction(applied(review.decide(id,decision(id,"EXPENSE",Map.of("categoryId",f.category)))));assertThat(t.categoryId()).isEqualTo(f.category);assertThat(t.type()).isEqualTo(TransactionType.EXPENSE);}
 @Test void unknownCashRejectsOppositeConflict(){var a=raw(true,"내계좌");raw(false,"내계좌");noFact(review.decide(a,decision(a,"UNRESOLVED",Map.of())));}
 @Test void pairConsumesTwoSourcesAndRequiresExplicitArchivedConsent(){UUID a=raw(true,"내계좌"),b=raw(false,"내계좌","975-******-01-015");var other=f.money.createAccount(new AccountInput("IBK","다른 소유 계좌",AccountRole.SPENDING,"975-******-01-015",null));f.db.update("update money_raw_notifications set review_deferred=true where id=?",b);
  var fields=new HashMap<String,Object>();fields.put("otherAccountId",other.id());fields.put("otherAccountVersion",other.version());fields.put("partnerId",b);fields.put("partnerVersion",f.money.notification(b).processingVersion());fields.put("partnerFingerprint",review.context(b).get("fingerprint"));
  noFact(review.decide(a,decision(a,"TRANSFER",fields)));fields.put("approveArchived",true);var request=decision(a,"TRANSFER",fields);var result=review.decide(a,request);var t=f.money.transaction(applied(result));assertThat(t.type()).isEqualTo(TransactionType.TRANSFER);assertThat(t.sources()).hasSize(2);assertThat(f.money.notification(b).state()).isEqualTo(ProcessingState.PROCESSED);assertThat(review.decide(a,request)).isEqualTo(result);assertThat(f.db.queryForObject("select count(*) from money_transactions",Long.class)).isEqualTo(1);}
 @Test void changedPartnerGraphRejectsEntirePair(){UUID a=raw(true,"내계좌"),b=raw(false,"내계좌","975-******-01-015");var other=f.money.createAccount(new AccountInput("IBK","다른 소유 계좌",AccountRole.SPENDING,"975-******-01-015",null));var request=decision(a,"TRANSFER",Map.of("otherAccountId",other.id(),"otherAccountVersion",other.version(),"partnerId",b,"partnerVersion",f.money.notification(b).processingVersion(),"partnerFingerprint",review.context(b).get("fingerprint")));f.db.update("update money_raw_notifications set processing_version=processing_version+1 where id=?",b);noFact(review.decide(a,request));}
 @Test void loanAllocationUsesExistingServiceAndOneCashImpact(){var raw=raw(true,"대출상환");var loan=f.web.saveLoan(null,new MoneyWebTypes.LoanInput("합성 대출","합성 은행","PERSONAL",new BigDecimal("10000"),new BigDecimal("10000"),null,null,null,null,f.account,null,null,"ACTIVE",null,0L));var t=f.money.transaction(applied(review.decide(raw,decision(raw,"LOAN_PAYMENT",Map.of("loanId",loan.id(),"loanVersion",loan.version(),"principal",5000,"interest",700,"fee",100)))));assertThat(t.type()).isEqualTo(TransactionType.LOAN_PAYMENT);assertThat(f.web.loan(loan.id()).remainingPrincipal()).isEqualByComparingTo("5000");assertThat(f.product.balance(f.account).amount()).isEqualByComparingTo("50000");}
 @Test void invalidLoanSplitRollsBackTemporaryFactAndAllSources(){var raw=raw(true,"대출상환");var loan=f.web.saveLoan(null,new MoneyWebTypes.LoanInput("합성 대출","합성 은행","PERSONAL",new BigDecimal("10000"),new BigDecimal("10000"),null,null,null,null,f.account,null,null,"ACTIVE",null,0L));noFact(review.decide(raw,decision(raw,"LOAN_PAYMENT",Map.of("loanId",loan.id(),"loanVersion",loan.version(),"principal",5000,"interest",900,"fee",100))));assertThat(f.db.queryForObject("select count(*) from money_transactions",Long.class)).isZero();assertThat(f.web.loan(loan.id()).remainingPrincipal()).isEqualByComparingTo("10000");}
 @Test void refundCapFailureLeavesNoGenericIncome(){var raw=raw(false,"환불");var original=f.product.save(null,new MoneyProductService.Entry(TransactionType.EXPENSE,f.account,null,BigDecimal.TEN,Instant.parse("2026-09-15T01:00:00Z"),"원소비",null,null,false,null,null,"합성 구매"));noFact(review.decide(raw,decision(raw,"REFUND",Map.of("refundOf",original.id(),"refundVersion",original.version()))));assertThat(f.db.queryForObject("select count(*) from money_transactions where type='INCOME'",Long.class)).isZero();}
 @Test void linkedRefundIsOneRefundAndNoIncome(){var raw=raw(false,"환불");var original=f.product.save(null,new MoneyProductService.Entry(TransactionType.EXPENSE,f.account,null,new BigDecimal("6000"),Instant.parse("2026-09-15T01:00:00Z"),"원소비",null,null,false,null,null,"합성 구매"));var t=f.money.transaction(applied(review.decide(raw,decision(raw,"REFUND",Map.of("refundOf",original.id(),"refundVersion",original.version())))));assertThat(t.type()).isEqualTo(TransactionType.REFUND);assertThat(t.refundOf()).isEqualTo(original.id());assertThat(t.sources()).hasSize(1);}
 @Test void unknownRefundWithoutOriginalCanAdmitAsUnresolved(){var raw=raw(false,"환불");var t=f.money.transaction(applied(review.decide(raw,decision(raw,"UNRESOLVED",Map.of()))));assertThat(t.meaningState()).isEqualTo("UNRESOLVED");assertThat(t.refundOf()).isNull();}
 @Test void staleAccountAndForeignCategoryFailWithoutCash(){var raw=raw(true,"합성카페");var request=decision(raw,"EXPENSE",Map.of());f.db.update("update money_accounts set version=version+1 where id=?",f.account);noFact(review.decide(raw,request));noFact(review.decide(raw,decision(raw,"EXPENSE",Map.of("categoryId",UUID.randomUUID()))));}
 @Test void failedParserCanBeCorrectedInlineWithoutChangingRawEvidence(){var raw=f.money.ingest(Map.of("sourcePackage","com.ibk.android.ionebank","text","합성 알림: 직접 확인 필요","postedAt","2026-09-16T01:00:00Z","currency","KRW")).notification();f.money.finishProcessing(raw.id(),ProcessingState.FAILED,"UNKNOWN_FORMAT");var context=review.context(raw.id());assertThat(context).containsEntry("manualRequired",true);var original=f.money.notification(raw.id()).rawPayload();var t=f.money.transaction(applied(review.decide(raw.id(),decision(raw.id(),"EXPENSE",Map.of("amount",1250,"direction","OUT","occurredAt","2026-09-16T01:00:00Z","currency","KRW","reason","소유자가 실제 은행 내역과 비교 확인")))));assertThat(t.amount()).isEqualByComparingTo("1250");assertThat(t.sources()).hasSize(1);assertThat(f.money.notification(raw.id()).rawPayload()).isEqualTo(original);}
 @Test void correctedVerifiedCashMayRemainUnresolvedWithoutSemanticPollution(){var raw=raw(true,"의미불명");var t=f.money.transaction(applied(review.decide(raw,decision(raw,"UNRESOLVED",Map.of("amount",6000,"direction","OUT","occurredAt","2026-09-16T01:00:00Z","reason","은행 원문과 정정 금액 확인")))));assertThat(t.amount()).isEqualByComparingTo("6000");assertThat(t.meaningState()).isEqualTo("UNRESOLVED");}
 @Test void loanReceiptReusesGuardedDrawAndNeverCountsAsIncome()throws Exception{f.db.execute(java.nio.file.Files.readString(java.nio.file.Path.of("src/main/resources/db/migration/V88__money_owner_loan_receipt.sql")));var raw=raw(false,"대출입금");var loan=f.web.saveLoan(null,new MoneyWebTypes.LoanInput("합성 신규 대출","은행","PERSONAL",new BigDecimal("10000"),BigDecimal.ZERO,null,null,null,null,f.account,null,null,"ACTIVE",null,0L));var t=f.money.transaction(applied(review.decide(raw,decision(raw,"LOAN_RECEIPT",Map.of("loanId",loan.id(),"loanVersion",loan.version(),"amount",5800,"direction","IN","occurredAt","2026-09-16T01:00:00Z","reason","신규 대출 실제 입금 확인")))));assertThat(t.type()).isEqualTo(TransactionType.LOAN_RECEIPT);assertThat(f.web.loan(loan.id()).remainingPrincipal()).isEqualByComparingTo("5800");assertThat(t.sources().getFirst().parseAttemptId()).isNotNull();}

 @Test void twoRawSourcesLinkToExistingCanonicalTransferWithoutAnotherCashFact(){UUID a=raw(true,"내계좌"),b=raw(false,"내계좌","975-******-01-015");var other=f.money.createAccount(new AccountInput("IBK","다른 소유 계좌",AccountRole.SPENDING,"975-******-01-015",null));var existing=f.product.save(null,new MoneyProductService.Entry(TransactionType.TRANSFER,f.account,other.id(),new BigDecimal("5800"),Instant.parse("2026-09-16T01:00:00Z"),"기존 이체",null,"보존 메모",false,null,null,"보존 제목"));var base=decision(a,"TRANSFER",Map.of("otherAccountId",other.id(),"otherAccountVersion",other.version(),"partnerId",b,"partnerVersion",f.money.notification(b).processingVersion(),"partnerFingerprint",review.context(b).get("fingerprint")));var command=new MoneyOwnerReviewService.Decision(base.requestId(),base.fingerprint(),"LINK_DUPLICATE",base.accountId(),base.otherAccountId(),existing.id(),base.accountVersion(),base.otherAccountVersion(),existing.version(),base.financial());assertThat(applied(review.decide(a,command))).isEqualTo(existing.id());assertThat(f.money.transaction(existing.id()).sources()).hasSize(2);assertThat(f.money.transaction(existing.id()).title()).isEqualTo("보존 제목");assertThat(f.db.queryForObject("select count(*) from money_transactions",Long.class)).isEqualTo(1);assertThat(f.money.notification(b).state()).isEqualTo(ProcessingState.PROCESSED);}

 @Test void provablyExternalMovementsInDifferentOwnedAccountsDoNotCreateFalseTransferReview(){f.money.createAccount(new AccountInput("IBK","합성 급여 계좌",AccountRole.INCOME_HUB,"975-******-01-015",null));UUID out=raw(true,"합성카페"),in=raw(false,"합성 급여","975-******-01-015");schedule(out);schedule(in);assertThat(processor().runOwner(f.owner)).isEqualTo(2);assertThat(f.db.queryForObject("select count(*) from money_transactions where meaning_state='CONFIRMED'",Long.class)).isEqualTo(2);var meaning=new MoneyMeaningService(f.db,()->f.owner,f.json);var queue=new MoneyReviewService(f.db,()->f.owner,f.web,f.product,meaning,f.json);assertThat(queue.queue(null,null,null,"PENDING",null,null,50,0).get("total")).isEqualTo(0L);}

}
